[4297] = { en = "Food for Baby", tier = 4,
  t = "Eten voor de baby",
  d = "Sprite darters zijn alleseters. Dat betekent dat ze zowel vlees als planten eten. Als je ei hier gaat uitkomen, kunnen we maar beter voorbereid zijn. Goed eten voor deze kleintjes is stukken vlees, rauw en sappig, of je het nu gelooft of niet. Ik heb nooit kunnen ontdekken waarom, maar het heeft iets te maken met Elunes plan voor de elfen... misschien moesten ze beschermers worden of zoiets, ik weet het niet.$B$BIk zorg voorlopig voor het ei. Waarom haal je niet een paar goede Silvermane Stalker Flanks voor me, zodat hij iets te eten heeft als hij uit het ei komt?",
  o = "Breng 5 Silvermane Stalker Flanks naar Agnar Beastamer in Hinterlands.",
  p = "Heb je dat vlees al gevonden, $N? Je kleine ei hier is bijna klaar om uit te komen. Als hij geen goede eerste maaltijd krijgt, haalt hij zijn eerste week misschien niet, en dat zou ik heel erg vinden.$B$BIk kan niet echt tegen je liegen, $N. Ik ben jaloers dat jij dit ei überhaupt hebt gekregen. Laat me geen spijt krijgen dat ik je zo help.",
  c = "Deze zijn prima, en als ik me niet vergis, is je kleine ei bijna klaar om uit te komen. Hoe voelt het? Je weet wel, dat je bijna $gvader:moeder; wordt? Haha, je had niet gedacht dat je zo'n verantwoordelijkheid zou krijgen, hè?",
  g = { {"alleseters", "omnivores (alleseter)"}, {"zowel", "both (zowel ... als: both ... and)"}, {"uitkomen", "to hatch"}, {"voorbereid", "prepared (voorbereiden)"}, {"rauw", "raw"}, {"sappig", "juicy"}, {"ontdekken", "to find out, discover"}, {"beschermers", "protectors (beschermer)"}, {"voorlopig", "for now"}, {"maaltijd", "meal"}, {"liegen", "to lie (tell lies)"}, {"jaloers", "jealous"}, {"überhaupt", "to begin with, at all"}, {"spijt", "regret"}, {"verantwoordelijkheid", "responsibility"} },
},

[2941] = { en = "The Borrower", tier = 4,
  t = "De lener",
  d = "Ik heb in mijn leven veel onderwerpen bestudeerd, en op dit moment ben ik gefascineerd door de snapjaws op het strand in Hinterlands. Er is er één die ik heel graag wil zien: een reusachtige snapjaw die Gammerita heet. Ik zou zelf willen gaan, maar mijn onderzoek houdt me hier. Ik denk dat een foto van haar het op één na beste is.$B$BBreng deze brief naar Curgle Cranklehop in Tanaris. Ze heeft een uitvinding voor me gemaakt die een afbeelding kan vastleggen. Ze noemde het een \"kiekje\", geloof ik...",
  o = "Breng de brief naar Curgle Cranklehop in Tanaris.",
  p = "Een brief -- voor mij?",
  c = "Ben jij weer een van Daryns stagiairs? Ze is een historica met veel kennis, $N. Je mag dankbaar zijn dat je onder haar leiding studeert.$b$bLaat me nu de Super Snapper FX pakken. Je gaat hem geweldig vinden!",
  g = { {"lener", "borrower"}, {"onderwerpen", "subjects, topics (onderwerp)"}, {"gefascineerd", "fascinated"}, {"reusachtige", "giant, huge (reusachtig)"}, {"onderzoek", "research"}, {"het op één na beste", "the next best thing"}, {"uitvinding", "invention"}, {"vastleggen", "to capture, record"}, {"kiekje", "snapshot (informal)"}, {"stagiairs", "interns (stagiair)"}, {"historica", "historian (f.)"}, {"kennis", "knowledge"}, {"dankbaar", "grateful"}, {"leiding", "leadership, guidance"} },
},

[2943] = { en = "Return to Troyas", tier = 4,
  t = "Terug naar Troyas",
  d = "Hier is het, $N. Wees alsjeblieft voorzichtig met mijn boek.$B$BGa nu maar snel. Ik weet zeker dat Troyas niet kan wachten tot je terug bent.",
  o = "Breng het boek naar Troyas Moonbreeze in Feathermoon Stronghold.",
  p = "Hallo, $N. Ben je in Darnassus geweest?",
