  g = { {"voorzichtig", "careful"}, {"niet kan wachten", "is eager, can't wait"}, {"meegebracht", "brought along (meebrengen)"}, {"uitstekend", "excellent"}, {"Ga nu maar snel", "now hurry along"} },
