[2944] = { en = "The Super Snapper FX", tier = 4,
  t = "De Super Snapper FX",
  d = "Jij mag als eerste mijn nieuwe uitvinding bekijken, $N. Je hoeft alleen maar te mikken op wat je wilt fotograferen en op de knop te drukken.$B$BWat was dat wezen uit Hinterlands dat je noemde? Gammerita? Nou, succes met het vinden van haar. Ik weet zeker dat Daryn heel blij zal zijn met het kiekje dat je haar brengt.$B$BHoe dan ook, hier is de Super Snapper. Veel plezier!",
  o = "Gebruik de Super Snapper FX om een kiekje van Gammerita te maken. Ga daarna terug naar Daryn Lightwind in Rut'theran Village.",
  p = "Zo, je bent eindelijk terug, $N. En je hebt het apparaat meegebracht dat Curgle voor me heeft gebouwd -- perfect.",
  c = "Nou! Curgles uitvinding heeft aan de verwachtingen voldaan.$B$BWord niet te enthousiast, maar weet dat ik tevreden ben met je werk, $N.$B$BWaar heb ik dat boek nou gelaten...",
  g = { {"uitvinding", "invention"}, {"mikken", "to aim"}, {"fotograferen", "to take a picture"}, {"knop", "button"}, {"wezen", "creature"}, {"noemde", "mentioned (noemen)"}, {"kiekje", "snapshot (informal)"}, {"Hoe dan ook", "in any case"}, {"apparaat", "device, contraption"}, {"verwachtingen", "expectations (verwachting)"}, {"voldaan", "lived up to (voldoen aan)"}, {"tevreden", "pleased, satisfied"} },
},

