[7003] = { en = "Zapped Giants", tier = 4,
  t = "Gezapte reuzen",
  d = "Ik moet iets aan de reuzen doen als ik hier blijf! Ze zijn zeker niet goed voor de zaken, of wel soms?$B$BIk werk aan een variant van een gnomische krimpstraal, maar ik bouw hem met superieure technologische vooruitgang van de GOBLINS! Om ongemakken voor mezelf te voorkomen, zoals de dood, wil ik dat jij hem uitprobeert op reuzen in Feralas, welke maakt niet uit. Als je ze hebt gekrompen, vind je verkleiningsresidu op ze - breng me wat terug!",
  o = "Gebruik Zorbin's Ultra-Shrinker om elke soort reus in Feralas te zappen tot een handzamer formaat. Breng 15 Miniaturization Residues van de gezapte reuzen naar Zorbin Fandazzle bij de kades van de Forgotten Coast, Feralas.",
  p = "Verkleiningsresidu is echt een waardevolle grondstof in de techniek, dat verzeker ik je! Nou ja, het is waardevol omdat het me helpt te zorgen dat de zapper niets teleurstellends doet, zoals ontploffen in de handen van de gebruiker.$B$BO, ik bedoel natuurlijk de andere zappers, niet die ik jou heb gegeven. Absoluut!",
  c = "Prachtastisch! Ik ben niet alleen blij dat je terug bent met het residu, maar ook dat al je belangrijke ledematen nog heel zijn! Dat wil zeggen, nou ja, er was nooit gevaar bij het gebruik van de Ultra-Shrinker, toch?$B$BIk waardeer wat je voor me hebt gedaan, $N. Je bent echt een vriend van goblins overal. Neem dit aan als teken van mijn dank!",
  g = { {"Gezapte", "zapped (zappen: here, to hit with a ray)"}, {"reuzen", "giants (reus)"}, {"of wel soms", "are they now?"}, {"gnomische", "gnomish (gnomisch)"}, {"krimpstraal", "shrinking ray"}, {"vooruitgang", "progress, advances"}, {"ongemakken", "inconveniences (ongemak)"}, {"gekrompen", "shrunk (krimpen)"}, {"verkleiningsresidu", "miniaturization residue"}, {"handzamer", "more manageable, handier (handzaam)"}, {"kades", "docks, quays (kade)"}, {"grondstof", "raw material, commodity"}, {"verzeker", "assure (verzekeren)"}, {"teleurstellends", "disappointing (teleurstellend)"}, {"ontploffen", "to explode"}, {"ledematen", "limbs (lidmaat)"}, {"waardeer", "appreciate (waarderen)"} },
},

[7721] = { en = "Fuel for the Zapping", tier = 4,
  t = "Brandstof voor het zappen",
  d = "Als ik tegen beter weten in blijf om aan de Forgotten Coast een technische winkel te hebben, moet ik iets doen aan deze lastige elementalen. Vervloekt zijn de krachten van ongecontroleerde elementaire magie, zeg ik!$B$BGelukkig voor mij, en nu ook voor jou, mijn hoopvolle agent provocateur, zijn de elementalen een ideale bron van ruwe kracht voor de verbetering van mijn Ultra-Shrinker - geef ze ervan langs, zeg ik! Bewaar daarbij wel de kernen van de waterelementalen voor me!",
  o = "Verzamel 10 Water Elemental Cores van de Sea Elementals en Sea Sprays langs de Forgotten Coast van Feralas, en breng ze terug naar Zorbin Fandazzle bij de kade daar.",
  p = "Ik kan je vervelen met de technische details over het nut van elementaire kernen, maar in plaats daarvan verleid ik je om deze belangrijke taak af te maken met waardevolle munten en prijzen. Nou, zeg eens, ben je klaar?",
  c = "Toptastisch! Deze kernen houden me een tijd aan het werk. Daar komt bij dat er nu minder elementalen langs de kust zijn, en misschien huil ik mezelf niet meer in slaap bij de gedachte dat ik mijn winkel heb geopend op misschien wel de slechtste plek die je je kunt voorstellen!$B$BBedankt, $N, voor alles wat je voor me hebt gedaan. Het kost me financieel echt veel, maar laat me je een vorm van dank geven die je vast begrijpt en waardeert... buit!",
  g = { {"Brandstof", "fuel"}, {"tegen beter weten in", "against my better judgment"}, {"lastige", "pesky, troublesome (lastig)"}, {"Vervloekt", "cursed"}, {"ongecontroleerde", "unchecked, uncontrolled"}, {"agent provocateur", "agent provocateur (someone who stirs up trouble)"}, {"verbetering", "improvement, refinement"}, {"geef ze ervan langs", "give them what for"}, {"kernen", "cores (kern)"}, {"vervelen", "to bore"}, {"nut", "use, usefulness"}, {"verleid", "tempt (verleiden)"}, {"Daar komt bij", "add to that"}, {"financieel", "financially"}, {"buit", "loot"} },
},

[7733] = { en = "Improved Quality", tier = 4,
  t = "Betere kwaliteit",
  d = "Ik heb een tip over een nog BETERE bron van huiden, als je dat al kunt geloven! In het noorden van Feralas - diep in Rage Scar Hold - leeft nog een grote groep yeti's. Ze zijn veel sterker dan die waar je eerder mee te maken had, dus als je een grotere uitdaging aankunt, moet je goed opletten!$B$BIk beloon je rijkelijk voor een stapel van tien van hun huiden. Breng ze hier naar mij, dan maken we onze zaak af.",
  o = "Breng 10 Rage Scar Yeti Hides naar Pratt McGrubben in Feathermoon Stronghold, Feralas.",
  p = "Als deze Rage Scar yetihuiden net zo goed zijn als die van hun soortgenoten in Feral Scar, zouden ze best eens zo sterk kunnen zijn als thorium!$B$BStel je voor!",
  c = "Uitstekend, uitstekend! Deze gaan heel goed werken - ik zie nu al dat ze veel harder worden als ze goed gelooid zijn.$B$BNogmaals bedankt voor je hulp, $N. Hier - neem een van mijn nieuwste creaties.",
  g = { {"kwaliteit", "quality"}, {"bron", "source"}, {"huiden", "hides (huid)"}, {"uitdaging", "challenge"}, {"aankunt", "can handle (aankunnen)"}, {"opletten", "to watch out, be careful"}, {"rijkelijk", "handsomely, richly"}, {"stapel", "stack"}, {"soortgenoten", "counterparts, own kind (soortgenoot)"}, {"best eens", "very well (might)"}, {"Stel je voor", "imagine that"}, {"gelooid", "cured, tanned (looien)"}, {"creaties", "creations (creatie)"} },
},

[7735] = { en = "Pristine Yeti Hide", tier = 4,
  t = "Gave yetihuid",
  d = "Je hebt een gave yetihuid gevonden die uitzonderlijk dik en stevig is - zelfs meer dan de huiden die je hebt gezien van de yeti's in Rage Scar.$B$BPratt McGrubben in Feathermoon Stronghold zoekt yetihuiden, dus deze huid kan voor hem heel interessant zijn.",
  o = "Breng de Pristine Yeti Hide naar Pratt McGrubben in Feathermoon Stronghold, Feralas.",
  p = "Wat is dit, $N - heb je iets bijzonders voor me?",
  c = "Ongelooflijk! Dit is misschien wel de opa van alle yetihuiden!$B$BJe kunt erop rekenen dat ik je ervoor betaal. Normaal betaal ik niet zoveel voor één huid, maar ik weet bijna zeker dat ik er iets bijzonders van kan maken. Bedankt dat je aan mij hebt gedacht, $N!",
  g = { {"Gave", "pristine, flawless (gaaf)"}, {"yetihuid", "yeti hide"}, {"uitzonderlijk", "exceptionally"}, {"stevig", "sturdy"}, {"bijzonders", "special (iets bijzonders: something special)"}, {"Ongelooflijk", "incredible"}, {"opa", "granddaddy, grandpa"}, {"Je kunt erop rekenen", "you can count on it"} },
},

[2844] = { en = "The Giant Guardian", tier = 4,
  t = "De reusachtige beschermer",
  d = "Ik ben nergens goed voor, $N. Ik moest op mijn kleine vriendinnetje Shay passen, en op een of andere manier is ze bij me weggelopen. Ik weet echt niet goed wat er gebeurd is, maar de laatste keer dat ik haar zag, liepen we door de ruïnes net ten noorden van hier.$B$BAlles ging prima, maar toen draaide ik me om, en... weg was ze.$B$BNu weet ik gewoon niet wat ik moet doen. Heb jij een idee, $N? Ik maak me vreselijk zorgen.$B$BHé, wat als jij Shay gaat zoeken? Jouw benen zijn veel sneller dan de mijne.",
  o = "Vind het verdwaalde nachtelfmeisje.",
  c = "O, ik ben zo blij dat je me gevonden hebt! Ik moet toegeven dat ik een beetje verdwaald ben... Maar is dit geen prachtige plek?",
  g = { {"reusachtige", "giant (reusachtig)"}, {"beschermer", "guardian, protector"}, {"nergens goed voor", "no good, good for nothing"}, {"passen", "to look after (passen op)"}, {"op een of andere manier", "somehow"}, {"ruïnes", "ruins (ruïne)"}, {"ten noorden van", "north of"}, {"vreselijk", "awfully, terribly"}, {"verdwaalde", "lost (verdwalen)"}, {"toegeven", "to admit"} },
},

[2845] = { en = "Wandering Shay", tier = 4,
  t = "Dwalende Shay",
  d = "Denk je dat je me kunt helpen de weg terug te vinden naar mijn vriend Rockbiter? Hij moest op me passen... Maar ik heb de neiging om af en toe weg te dwalen. Er is gewoon zoveel te zien, en ik raak zo snel afgeleid.$B$BMaar er is één ding dat altijd werkt om mijn aandacht te trekken.$B$BIn deze kist vind je een bel die heel kostbaar voor me is. Ik ben dol op het geluid ervan. Ik beloof je: als ik wegdwaal, hoef je hem alleen maar te luiden en dan kom ik terugrennen.",
  o = "Pak Shay's Bell uit de kist.$B$BBegeleid Shay Leafrunner naar het kamp van Rockbiter.",
  p = "Ik begon me zorgen over je te maken! Heel erg bedankt dat je Shay naar huis hebt gebracht, $N.",
  c = "Wat? Zeg je dat deze bel werkt als Shay wegloopt? Nou, wat zeg je daarvan!$B$BOmdat je zoveel voor me hebt gedaan, hier, voor jou, $N.",
  e = "Breng Shay Leafrunner naar het kamp van Rockbiter",
  g = { {"Dwalende", "wandering (dwalen)"}, {"neiging", "tendency"}, {"af en toe", "now and then"}, {"weg te dwalen", "to wander off (wegdwalen)"}, {"afgeleid", "distracted (afleiden)"}, {"aandacht", "attention"}, {"kist", "chest"}, {"kostbaar", "precious"}, {"dol op", "very fond of"}, {"luiden", "to ring (a bell)"}, {"Begeleid", "escort (begeleiden)"}, {"wat zeg je daarvan", "how about that"} },
},

[2879] = { en = "The Stave of Equinex", tier = 4,
  t = "De Stave of Equinex",
  d = "Deze staf zou de Stave of Equinex kunnen zijn! De Stave of Equinex is eigenlijk een sleutel. Je opent er de Equinex Monolith mee in de Ruins of Ravenwind, op het vasteland ten westen van de Dream Bough.$B$BZoek de vier vlammen die nog in die ruïnes branden: Samha, Imbel, Byltan en Lahassa. Haal hun essentie op. Ga dan bij de Equinex Monolith staan en gebruik de essenties om de staf met energie te laden. Als dit echt de Stave of Equinex is, kun je de Monolith openen en er een heilig artefact uit halen.",
  o = "Laad Troyas' Stave met energie en vind de Equinex Monolith.",
  p = "De Equinex Monolith staat zwijgend tussen de ruïnes. Wat zou erin verborgen zijn?",
  c = "Je kunt de geladen staf bijna niet vasthouden. Zijn kracht dreunt door je lichaam.$B$BJe steekt je hand uit naar het koude oppervlak van de Equinex Monolith...$B$BEen klein deurtje gaat open, zodat je erin kunt reiken en het artefact kunt pakken.$B$BLichtstralen vullen de omgeving rond de Equinex Monolith.",
  g = { {"staf", "staff, stave"}, {"vasteland", "mainland"}, {"vlammen", "flames (vlam)"}, {"essentie", "essence"}, {"met energie te laden", "to energize (met energie laden)"}, {"heilig", "sacred, holy"}, {"artefact", "artifact"}, {"zwijgend", "silently"}, {"verborgen", "hidden (verbergen)"}, {"geladen", "charged, energized (laden)"}, {"dreunt", "rumbles (dreunen)"}, {"oppervlak", "surface"}, {"reiken", "to reach"}, {"Lichtstralen", "beams of light (lichtstraal)"}, {"omgeving", "surroundings, area"} },
},

[2942] = { en = "The Morrow Stone", tier = 4,
  t = "De Morrow Stone",
  d = "Op het moment dat je het artefact uit de Monolith haalt, voel je dat de energie in de Stave of Equinex begint te verdwijnen.",
  o = "Breng de Sparkling Stone en de Stave of Equinex terug naar Troyas Moonbreeze in Feathermoon Stronghold.",
  p = "Ik ben blij dat je terug bent, $N. Ik ben benieuwd naar wat je hebt ontdekt.",
  c = "Ik heb gelezen sinds je weg bent, $N. De steen die je hebt gevonden heet de Morrow Stone. Ik weet nog niet helemaal zeker wat het doel ervan is, maar je kunt er zeker van zijn dat het van groot belang is, als hij zo in de Equinex Monolith verborgen was.$B$BIk ga verder met mijn studie, en ik hoop dat ik in de toekomst op je kan rekenen, $N. Bedankt voor al je hulp.",
  g = { {"artefact", "artifact"}, {"verdwijnen", "to fade, disappear"}, {"benieuwd", "eager (to know), curious"}, {"ontdekt", "discovered, found (ontdekken)"}, {"doel", "purpose"}, {"van groot belang", "of great significance"}, {"verborgen", "hidden (verbergen)"}, {"studie", "studies"}, {"rekenen", "to count (rekenen op: count on)"} },
},

[3445] = { en = "The Sunken Temple", tier = 4,
  t = "De Sunken Temple",
  d = "Ik heb gehoord van een plek die diep onder het aardoppervlak ligt -- daarheen verbannen door krachten die groter zijn dan ik ooit heb gezien.$B$BAls je meer wilt weten over deze plek, de Sunken Temple, zoek dan een goblin die Marvon Rivetseeker heet. Net als Troyas en ik heeft hij veel oude gebieden van de wereld bestudeerd. Het laatste wat men van hem weet, is dat hij zijn huis in Ratchet verliet om de trollenruïnes in Tanaris te onderzoeken.$B$BSucces met het vinden van hem; er is al een tijd niets meer van hem gehoord.",
  o = "Vind Marvon Rivetseeker in Tanaris.",
  c = "Ja, de Sunken Temple. Ik kan zeggen dat ik hem met eigen ogen heb gezien. Misschien wil je er meer over horen?$B$BJe ziet eruit als iemand die van avontuur houdt -- ik weet dingen die je misschien zullen boeien...",
  g = { {"aardoppervlak", "surface of the earth"}, {"verbannen", "banished (verbannen)"}, {"krachten", "powers (kracht)"}, {"gebieden", "areas (gebied)"}, {"bestudeerd", "studied (bestuderen)"}, {"men", "people, one (impersonal)"}, {"verliet", "left (verlaten)"}, {"trollenruïnes", "troll ruins"}, {"onderzoeken", "to study, investigate"}, {"met eigen ogen", "with my own eyes"}, {"avontuur", "adventure"}, {"boeien", "to intrigue, fascinate"} },
},

[4041] = { en = "The Videre Elixir", tier = 4,
  t = "Het Videre Elixir",
  p = "Breng me een Evoroot, en dan kan ik dat Videre Elixir voor je maken, hoor.$B$BIk weet van alles over kruiden en alchemie... Zeg, laat me je eens vertellen over de keer dat ik goud maakte uit de kaas die ik als lunch zou eten... hé... Waar ga je heen?",
  c = "Zo, dus je hebt de oude Miblon mooi beetgenomen, hè?",
  g = { {"kruiden", "herbs (kruid)"}, {"alchemie", "alchemy"}, {"van alles", "all kinds of things"}, {"goud", "gold"}, {"kaas", "cheese"}, {"beetgenomen", "fooled, tricked (beetnemen)"}, {"mooi", "nicely, well (here: properly)"} },
},

[2878] = { en = "Corrupted Songflower", tier = 4,
  t = "Verdorven Songflower",
  p = "Je hebt een zieke, verdorven versie gevonden van wat een songflower lijkt te zijn. Er komt een scherpe, ongezonde geur van de plant af. De plant heeft dringend zorg nodig om weer normaal te worden.",
  c = "Je smeert wat Cenarion plant salve op de songflower. Meteen begint hij zijn verdorven vorm af te werpen, en hij bloeit op tot een levendige, gezonde plant.",
  g = { {"Verdorven", "corrupted"}, {"zieke", "sickly, ill (ziek)"}, {"scherpe", "pungent, sharp (scherp)"}, {"ongezonde", "unhealthy (ongezond)"}, {"geur", "odor, smell"}, {"dringend", "urgently, desperately"}, {"zorg", "care, attention"}, {"smeert", "apply, spread (smeren)"}, {"af te werpen", "to shed, throw off (afwerpen)"}, {"bloeit op", "blossoms (opbloeien)"}, {"levendige", "vibrant, lively (levendig)"} },
},

[7725] = { en = "Again With the Zapped Giants", tier = 4,
  t = "Alweer gezapte reuzen",
  d = "Ik weet dat je al residu voor me hebt verzameld... maar als je zin hebt in een toegift van deze leuke activiteit, kan ik altijd meer residu gebruiken.$B$BIk kan je deze keer lang niet zoveel beloning geven, maar ik vertel graag het goede nieuws over je hulp aan al mijn goblinvrienden met oren.$B$BGeloof me, $gmeneer:mevrouw;, als ik zeg dat deze goblins behoorlijk grote oren hebben.",
  o = "Gebruik Zorbin's Ultra-Shrinker om elke soort reus in Feralas te zappen tot een handzamer formaat. Breng 10 Miniaturization Residues van de gezapte reuzen naar Zorbin Fandazzle bij de kades van de Forgotten Coast, Feralas.",
  p = "Ah, de vruchten van onderzoek en gebruik, in de vorm van heerlijk, heerlijk residu. Nou ja, ik bedoel, ik proef het natuurlijk niet als ik het bestudeer.$B$BNiet veel.",
